    return {
      statusCode: 200,
      headers: {
        'X-Lambda-Request-Id': awsRequestId,
        'Content-Type': `application/json`,
        'Cache-Control': `private, no-store`,
      },
      body: JSON.stringify({consents}),
    };

import {
  boolean,
  coerce,
  enums,
  literal,
  object,
  optional,
  pick,
  string,
  union,
} from 'superstruct';

const booleanString = coerce(
  boolean(),
  union([literal(`true`), literal(`false`), literal(undefined)]),
  (value) => value === `true`,
);

const allQueryParamsStruct = object({
  envName: enums([`dev`, `sit`, `stage`, `prod`]),
  preview: booleanString,
  mock: optional(union([literal(`B2B`), literal(`B2C`)])),
  loggedIn: booleanString,
  phone: optional(string()),
  marketId: string(),
  languageTag: string(),
  organisationId: optional(string()),
  enableConsents: optional(string()),
  rotatingVerifySecret: optional(
    coerce(
      object({headerName: string(), headerValue: string()}),
      string(),
      (authHeader) => {
        const [headerName, headerValue] = authHeader.split(`:`);

        return {headerName, headerValue};
      },
    ),
  ),
});

export const appModelQueryParamsStruct = pick(allQueryParamsStruct, [
  `envName`,
  `preview`,
  `loggedIn`,
  `marketId`,
  `languageTag`,
  `rotatingVerifySecret`,
]);

