  `envName`,
  `preview`,
  `mock`,
  `marketId`,
  `languageTag`,
  `organisationId`,
  `enableConsents`,
  `rotatingVerifySecret`,
]);

export const verifyCodeQueryParamsStruct = pick(allQueryParamsStruct, [
