import {isGlobalFeatureFlagsEnabled} from '@smart/utils';
import {useEffect, useState} from 'react';
import type {DataContext} from '../components/MyAccountContextWrapper/MyAccountContextWrapper';
import {UsedFeatureFlags} from '../constants/common';
import type {ConsentsData} from '../utils/fetch-consents';
import {fetchConsents} from '../utils/fetch-consents';
import {useFeatureAppEnv} from './use-feature-app-env';
import {useLocale} from './use-locale';

export type ConsentsType = DataContext<ConsentsData> & {
  fetching: boolean;
  fetchData: (organisationId?: string) => void;
};

export function useConsents(): ConsentsType {
  const {
    baseUrl,
    featureServices: {'endpoint-directory': endpointDirectory},
    config,
  } = useFeatureAppEnv();
  const mock = config?.mock;

  const locale = useLocale();
  const [data, setData] = useState<ConsentsData>();
  const [error, setError] = useState(null);
  const [isLoaded, setIsLoaded] = useState(false);
  const [fetching, setFetching] = useState(false);
  const [orgId, setOrgId] = useState<string | undefined>();

  const fetchData = (organisationId?: string) => {
    setOrgId(organisationId);
    setFetching(true);
  };

  useEffect(() => {
    if (window.location.search.includes(`firstlogin=true`)) fetchData();
  }, []);
  const {marketId} = useLocale();
  const enableConsents = isGlobalFeatureFlagsEnabled(
    UsedFeatureFlags.ENABLE_MYACCOUNT_CONSENT,
    marketId,
  );
  useEffect(() => {
    if (fetching) {
      setIsLoaded(false);
      setError(null);

      const abortController = new AbortController();

      fetchConsents(
        baseUrl,
        {
          endpointDirectory,
          locale,
          mock,
          signal: abortController.signal,
        },
        orgId,
        enableConsents,
      )
        .then((response) => {
          setData(response);
        })
        .catch((err) => {
          if (!abortController.signal.aborted) {
            setError(err);
          }
        })
        .finally(() => {
          setIsLoaded(true);
          setFetching(false);
        });

      return () => abortController.abort();
    }
    return;
  }, [baseUrl, fetching, endpointDirectory, locale]);

  return {
    fetchData,
    fetching,
    isLoaded,
    error,
    data,
  };
}

import type {ConsentsChange} from '../../bff/consents/edit/coerce-body-params';
import type {FetchFromBFFOptions} from './fetch-params';
import {createFetchSearchParams} from './fetch-params';
import {convertToPrivate} from './private-base-url';

export interface ConsentsData {
  consents: Consents;
}

export interface Consents {
  consentVocPhone?: boolean;
  consentVocEmail?: boolean;
  consentPhone?: boolean;
  termsOfService?: boolean;
  consentDirectMail?: boolean;
  consentEmail?: boolean;
  privacyPolicy?: boolean;
  newsletter?: boolean;
  verifiedPhone?: string;
}

export async function fetchConsents(
  baseUrl: string = ``,
  options: FetchFromBFFOptions,
  organisationId?: string,
  enableConsents?: boolean,
): Promise<ConsentsData> {
  const searchParams = createFetchSearchParams(options);
  const {signal} = options;

  if (organisationId) {
    searchParams.set(`organisationId`, organisationId);
  }
  if (enableConsents) {
    searchParams.set(`enableConsents`, String(enableConsents));
  }

  const url = `${convertToPrivate(
    baseUrl,
  )}/bff/consents?${searchParams.toString()}`;
  const response = await fetch(url, signal ? {signal} : undefined);

  if (!response.ok) {
    throw Error(`Could not fetch consents.`);
  }

